Функция ПолучитьСальдоСчета(Счет) Экспорт

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
	|	СУММА(Данные.Дебет) КАК ОборотДт,
	|	СУММА(Данные.Кредит) КАК ОборотКт
	|ИЗ
	|	(ВЫБРАТЬ
	|		Хозрасчетный.Сумма КАК Дебет,
	|		0 КАК Кредит
	|	ИЗ
	|		РегистрБухгалтерии.Хозрасчетный КАК Хозрасчетный
	|	ГДЕ
	|		Хозрасчетный.СчетДт В ИЕРАРХИИ (&Счет)
	|
	|	ОБЪЕДИНИТЬ ВСЕ
	|
	|	ВЫБРАТЬ
	|		0,
	|		Хозрасчетный.Сумма
	|	ИЗ
	|		РегистрБухгалтерии.Хозрасчетный КАК Хозрасчетный
	|	ГДЕ
	|		Хозрасчетный.СчетКт В ИЕРАРХИИ (&Счет)) КАК Данные";

	Запрос.УстановитьПараметр("Счет", Счет);

	Выборка = Запрос.Выбрать();

	ОборотДт = 0;
	ОборотКт = 0;
	Если Выборка.Следующий() Тогда
		ОборотДт = ?(Выборка.ОборотДт = Null, 0, Выборка.ОборотДт);
		ОборотКт = ?(Выборка.ОборотКт = Null, 0, Выборка.ОборотКт);
	КонецЕсли;

	Если Счет.Вид = ВидСчета.Пассивный Тогда
		Сальдо = ОборотКт - ОборотДт;
	Иначе
		Сальдо = ОборотДт - ОборотКт;
	КонецЕсли;

	Возврат Сальдо;

КонецФункции
```
